1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface Damage {
9	  itemType: string;
10	  amount: number;
11	}
12	
13	export interface Incident {
14	  cause: string;
15	  damages: Damage[];
16	}
17	
18	export type Step =
19	  | { op: "quote"; items: Item[] }
20	  | { op: "claim"; policy: number; incident: Incident };
21	
22	export interface Customer {
23	  yearsWithMHPCO: number;
24	}
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type QuoteResult = { premium: number };
32	export type ClaimResult = { payout: number; remainingCap: number };
33	export type Result = QuoteResult | ClaimResult;
34	
35	export interface ScenarioOutcome {
36	  results: Result[];
37	}
38	
39	/** Rounds up to whole G (the MHPCO's favour), ignoring binary floating-point noise. */
40	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
41	
42	const BASE_PREMIUM: Record<string, number> = {
43	  sword: 100,
44	  amulet: 60,
45	  staff: 80,
46	  potion: 40,
47	  rune: 25,
48	  moonstone: 25,
49	};
50	
51	const INSURANCE_VALUE: Record<string, number> = {
52	  sword: 1000,
53	  amulet: 600,
54	  staff: 800,
55	  potion: 400,
56	  rune: 250,
57	  moonstone: 250,
58	};
59	
60	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
61	const POLICY_FEE = 5;
62	
63	const COMPONENT_TYPES = ["rune", "moonstone"];
64	const BUILDING_BLOCK_SIZE = 3;
65	const BUILDING_BLOCK_BASE_PREMIUM = 60;
66	
67	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
68	
69	const sum = (amounts: number[]): number => amounts.reduce((a, b) => a + b, 0);
70	
71	const countOfType = (items: Item[], type: string): number =>
72	  items.filter((item) => item.type === type).length;
73	
74	/**
75	 * Components of one kind are bundled into building blocks of 3, each charged at
76	 * the special block rate; leftovers are charged individually.
77	 */
78	const componentGroupBasePremium = (type: string, count: number): number => {
79	  const blocks = Math.floor(count / BUILDING_BLOCK_SIZE);
80	  const singles = count % BUILDING_BLOCK_SIZE;
81	  return blocks * BUILDING_BLOCK_BASE_PREMIUM + singles * BASE_PREMIUM[type];
82	};
83	
84	const CURSED_SURCHARGE_RATE = 0.5;
85	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
86	const HIGH_ENCHANTMENT_LEVEL = 5;
87	
88	/**
89	 * A premium modifier as a multiplicative factor: a positive rate loads the premium,
90	 * a negative rate discounts it, and a modifier that does not apply leaves it untouched.
91	 */
92	const rateFactor = (applies: boolean, rate: number): number => (applies ? 1 + rate : 1);
93	
94	const isCursed = (item: Item): boolean => item.cursed === true;
95	const isHighlyEnchanted = (item: Item): boolean =>
96	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
97	
98	/** Risk surcharges attach to the individual item that carries the risk, and compound. */
99	const riskMultiplierOf = (item: Item): number =>
100	  rateFactor(isCursed(item), CURSED_SURCHARGE_RATE) *
101	  rateFactor(isHighlyEnchanted(item), HIGH_ENCHANTMENT_SURCHARGE_RATE);
102	
103	/** Main items are priced one by one off the base price list, each carrying its own risk load. */
104	const mainItemsPremium = (items: Item[]): number =>
105	  sum(
106	    items
107	      .filter((item) => !isComponent(item))
108	      .map((item) => BASE_PREMIUM[item.type] * riskMultiplierOf(item)),
109	  );
110	
111	/**
112	 * Components are priced per kind, so alike ones can bundle into building blocks.
113	 * Pricing by count means individual risk flags are not visible here — no test covers
114	 * a cursed component yet, so this stays as-is rather than being fixed speculatively.
115	 */
116	const componentsPremium = (items: Item[]): number =>
117	  sum(COMPONENT_TYPES.map((type) => componentGroupBasePremium(type, countOfType(items, type))));
118	
119	/** Base price list plus per-item risk loading — everything before customer-level modifiers. */
120	const riskLoadedPremiumOf = (items: Item[]): number =>
121	  mainItemsPremium(items) + componentsPremium(items);
122	
123	const LOYALTY_DISCOUNT_RATE = -0.2;
124	/** Loyalty begins at the start of the second year: 1 year does not qualify, 2 do. */
125	const LOYALTY_THRESHOLD_YEARS = 2;
126	
127	const isLoyal = (customer: Customer): boolean =>
128	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
129	
130	const CONTRACT_DISCOUNT_RATE = -0.15;
131	
132	/**
133	 * Customer-level modifiers apply to the whole quote and compound. A customer's very
134	 * first insurance carries the assessment surcharge; every contract after it is
135	 * discounted instead. `previousQuotes` counts quotes already given to this customer.
136	 */
137	const customerMultiplierOf = (customer: Customer, previousQuotes: number): number => {
138	  const isFirstInsurance = previousQuotes === 0;
139	  return (
140	    rateFactor(isLoyal(customer), LOYALTY_DISCOUNT_RATE) *
141	    rateFactor(isFirstInsurance, FIRST_INSURANCE_SURCHARGE_RATE) *
142	    rateFactor(!isFirstInsurance, CONTRACT_DISCOUNT_RATE)
143	  );
144	};
145	
146	const quote = (items: Item[], customer: Customer, previousQuotes: number): QuoteResult => {
147	  const premiumBeforeFee =
148	    riskLoadedPremiumOf(items) * customerMultiplierOf(customer, previousQuotes);
149	  return { premium: roundUpToWholeG(premiumBeforeFee) + POLICY_FEE };
150	};
151	
152	/**
153	 * Steps are not independent: each one is answered in the light of the steps before it,
154	 * so the scenario is walked as a fold that threads what has happened so far.
155	 */
156	interface Policy {
157	  items: Item[];
158	  remainingCap: number;
159	}
160	
161	interface ScenarioState {
162	  quotesSoFar: number;
163	  /** Policies issued so far, keyed by the step index of the quote that created each. */
164	  policies: Record<number, Policy>;
165	}
166	
167	const INITIAL_STATE: ScenarioState = { quotesSoFar: 0, policies: {} };
168	
169	const DEDUCTIBLE = 100;
170	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
171	
172	const insuranceSumOf = (items: Item[]): number =>
173	  sum(items.map((item) => INSURANCE_VALUE[item.type]));
174	
175	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
176	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
177	const FULL_REIMBURSEMENT_RATE = 1;
178	
179	/** Heavily enchanted items are only half covered; everything else is reimbursed in full. */
180	const reimbursementRateOf = (item: Item): number =>
181	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL
182	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
183	    : FULL_REIMBURSEMENT_RATE;
184	
185	/**
186	 * A damage names its item by type. A damage naming a type the policy does not cover is
187	 * outside anything the specification describes, so it is reimbursed at the plain rate
188	 * rather than given a rule of its own.
189	 */
190	const rateForDamage = (damage: Damage, items: Item[]): number => {
191	  const damagedItem = items.find((item) => item.type === damage.itemType);
192	  return damagedItem === undefined ? FULL_REIMBURSEMENT_RATE : reimbursementRateOf(damagedItem);
193	};
194	
195	/**
196	 * Each damage is reimbursed at the rate its own item earns, and the deductible is borne
197	 * by the incident as a whole — so the rates are applied first and the sum reduced once.
198	 */
199	const reimbursableDamageOf = (incident: Incident, items: Item[]): number =>
200	  sum(incident.damages.map((damage) => damage.amount * rateForDamage(damage, items)));
201	
202	/** Draws the payout down against the policy's remaining cap, reporting what is left. */
203	const settleClaimAgainstCap = (incident: Incident, policy: Policy): ClaimResult => {
204	  const payout = Math.max(0, reimbursableDamageOf(incident, policy.items) - DEDUCTIBLE);
205	  return { payout, remainingCap: policy.remainingCap - payout };
206	};
207	
208	/** Records a policy under its step index, leaving the rest of the scenario state untouched. */
209	const withPolicy = (state: ScenarioState, policyKey: number, policy: Policy): ScenarioState => ({
210	  ...state,
211	  policies: { ...state.policies, [policyKey]: policy },
212	});
213	
214	const applyStep = (
215	  state: ScenarioState,
216	  step: Step,
217	  customer: Customer,
218	  stepIndex: number,
219	): { state: ScenarioState; result: Result } => {
220	  if (step.op === "quote") {
221	    const policy: Policy = {
222	      items: step.items,
223	      remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(step.items),
224	    };
225	    return {
226	      state: withPolicy({ ...state, quotesSoFar: state.quotesSoFar + 1 }, stepIndex, policy),
227	      result: quote(step.items, customer, state.quotesSoFar),
228	    };
229	  }
230	  const policy = state.policies[step.policy];
231	  const result = settleClaimAgainstCap(step.incident, policy);
232	  return {
233	    state: withPolicy(state, step.policy, { ...policy, remainingCap: result.remainingCap }),
234	    result,
235	  };
236	};
237	
238	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
239	  const results: Result[] = [];
240	  let state = INITIAL_STATE;
241	  for (const [stepIndex, step] of scenario.steps.entries()) {
242	    const stepOutcome = applyStep(state, step, scenario.customer, stepIndex);
243	    state = stepOutcome.state;
244	    results.push(stepOutcome.result);
245	  }
246	  return { results };
247	};
